"use client";

import Image from "next/image";
import { useState } from "react";
import { cn } from "@/lib/utils";
import { ProductThumb } from "../cart/product-thumb";

/**
 * Static product imagery: a real render of the 3D model (generated by
 * `npm run render:products`), falling back to a vector drawing if the
 * render file is missing.
 */
export function ProductFallback({
  colorKey,
  colorHex,
  accentHex,
  className,
  priority,
  alt = "",
  sizes = "(max-width: 768px) 90vw, 50vw",
}: {
  colorKey: string;
  colorHex: string;
  accentHex: string;
  className?: string;
  priority?: boolean;
  alt?: string;
  sizes?: string;
}) {
  const [failed, setFailed] = useState(false);
  return (
    <div className={cn("relative grid size-full place-items-center", className)}>
      {failed ? (
        <ProductThumb colorHex={colorHex} accentHex={accentHex} className="w-[70%] max-w-[560px]" title={alt || undefined} />
      ) : (
        <Image
          src={`/images/renders/${colorKey}.png`}
          alt={alt}
          fill
          priority={priority}
          sizes={sizes}
          className="object-contain"
          onError={() => setFailed(true)}
        />
      )}
    </div>
  );
}
